<?php require_once __DIR__ . '/icons.php';
// «Por WhatsApp» en Solicitudes: el último envío de documentos al chat de cada solicitud (historia automática o respuesta «Aprobado»).
$waKinds = ['history' => ['Automático', 'Historia que el sistema envió sola al encontrarla o al cargar su PDF'], 'response' => ['Respuesta «Aprobado»', 'Documentos que adjuntó la persona encargada al responder']];
$waStates = ['sent' => 'Entregado a WhatsApp', 'queued' => 'En cola', 'sending' => 'Enviando', 'failed' => 'No se pudo enviar', 'uncertain' => 'Sin confirmar', 'cancelled' => 'Cancelado'];
?><div class="table-wrap"><table class="responsive-table requests-table whatsapp-table" role="table"><thead role="rowgroup"><tr role="row"><th scope="col" role="columnheader">Paciente</th><th scope="col" role="columnheader">Radicado / fecha</th><th scope="col" role="columnheader">Envío por WhatsApp</th><th scope="col" role="columnheader">Estado</th><th scope="col" role="columnheader">Acciones</th></tr></thead><tbody role="rowgroup">
<?php foreach ($deliverySearch['rows'] as $row): [$kindLabel, $kindHelp] = $waKinds[$row['wa_kind']] ?? ['Envío', '']; ?><tr role="row" data-row-open>
<td role="cell" data-label="Paciente"><strong class="cell-name" title="<?= h($row['claimed_name']) ?>"><?= h($row['claimed_name']) ?></strong><?php if ($row['document_number']): ?><small class="cell-doc"><span class="doc-type"><?= h($row['document_type']) ?></span> <span class="mono"><?= h($row['document_number']) ?></span></small><?php else: ?><small>Documento no conservado</small><?php endif ?></td>
<td role="cell" data-label="Radicado / fecha"><strong class="mono ref"><?= h($row['reference']) ?></strong><small class="mono nowrap"><?= h(date('d/m/Y H:i', strtotime($row['created_at']))) ?></small></td>
<td role="cell" data-label="Envío por WhatsApp"><span class="pill <?= $row['wa_kind'] === 'history' ? 'info' : 'ok' ?>" title="<?= h($kindHelp) ?>"><?= ui_icon('chat', 14) ?><?= h($kindLabel) ?></span><small class="mono">+<?= h($row['wa_phone']) ?></small></td>
<td role="cell" data-label="Estado"><div class="status-stack"><span class="pill <?= ui_tone((string)$row['wa_status']) ?>"><?= h($waStates[$row['wa_status']] ?? $row['wa_status']) ?></span><?php if ($row['wa_sent_at']): ?><small class="mono nowrap"><?= h(date('d/m/Y H:i', strtotime($row['wa_sent_at']))) ?></small><?php else: ?><small>Creado <?= h(date('d/m/Y H:i', strtotime($row['wa_created_at']))) ?> · <?= (int)$row['wa_attempts'] === 1 ? '1 intento' : (int)$row['wa_attempts'] . ' intentos' ?></small><?php endif ?><?php if ($row['wa_error'] && $row['wa_status'] !== 'sent'): ?><small class="danger with-icon"><?= ui_icon('alert', 14) ?><?= h($row['wa_error']) ?></small><?php endif ?></div></td>
<td role="cell" data-label="Acciones"><div class="row-actions"><a class="history-button small" data-history-modal aria-haspopup="dialog" href="?page=case-history&amp;id=<?= (int)$row['id'] ?>" aria-label="Historial del caso <?= h($row['reference']) ?>" title="Historial del caso"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 12a9 9 0 1 0 3-6.7L3 8"/><path d="M3 3v5h5M12 7v5l3 2"/></svg></a><a class="button secondary eye-button" data-delivery-modal data-row-primary aria-haspopup="dialog" aria-controls="delivery-modal" href="?page=delivery&amp;id=<?= (int)$row['id'] ?>&amp;p=<?= (int)$deliverySearch['page'] ?>" aria-label="Ver solicitud <?= h($row['reference']) ?>" title="Ver la solicitud"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></a></div></td>
</tr><?php endforeach ?></tbody></table></div>
